  "struct_hints": [
    {
      "offset": 2,
      "meaning": "a6 byte field containing a primary packet length byte for time-on-air calculation"
    },
    {
      "offset": 3,
      "meaning": "a6 fallback packet length byte used when offset 2 is zero"
